export default function message({translations,title,author}){if(!Array.isArray(translations)||translations.length!==1||typeof translations[0]?.translatedText!=='string'||!translations[0].translatedText.trim())throw Error('Translation was not returned');const text='✒️ Poem of the day:
'+title+' by '+author+'

'+translations[0].translatedText+'
☁️';if(text.length>4096)throw Error('Telegram message exceeds 4096 characters');return{text}}
